// Textured ground: tileable PBR surfaces (generated by tools/textures/gen.py)
// blended per pixel from per-vertex splat weights. Grass is the base layer;
// rock, gravel and snow are mixed in by height so rock pokes through grass
// and stones sit proud of the dirt instead of cross-fading. Rock is
// triplanar so cliffs don't smear.
import * as THREE from 'three';
import { addLampLights, lampsOn } from './lamps.js';

const url = (n) => new URL(`./assets/textures/${n}.webp`, import.meta.url).href;
const loader = new THREE.TextureLoader();
const cache = new Map();
const pending = [];

export function groundTexture(name, kind, renderer) {
  const key = `${name}_${kind}`;
  if (cache.has(key)) return cache.get(key);
  let tex;
  pending.push(new Promise((res) => (tex = loader.load(url(key), res, undefined, res))));
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
  tex.colorSpace = kind === 'albedo' ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  cache.set(key, tex);
  return tex;
}

// Lets other asset loaders join the start-up wait.
export function trackLoad(promise) {
  pending.push(promise.catch((e) => console.error(e)));
}

// Resolves once every asset requested so far has loaded (or failed).
export function texturesReady() {
  return Promise.all(pending);
}

// Surface sets per biome, keyed by the name in its biomes.js `look.ground`.
export const GROUND_SETS = {
  alpine: { base: 'grass', rock: 'rock', gravel: 'gravel', snow: 'snow' },
  // Rolling moorland: gentler hills, granite, heather and bracken, no snow.
  dartmoor: {
    base: 'moor', rock: 'granite', gravel: 'gravel', snow: 'snow', tuft: 'moor_tuft',
    // Dark heathery hollows, tawny moor grass, rusty bracken patches.
    patchLo: [0.72, 0.66, 0.62], patchHi: [1.12, 1.0, 0.8], patchC: [1.15, 0.7, 0.45, 0.7],
    relief: 0.5, maxRelief: 70, snowLine: 1e5, treeDensity: 0.15,
  },
  // Hillside Suburbs: mown lawns and verges, gentle hills, few wild trees,
  // and only the odd clump of long grass.
  suburbs: {
    base: 'lawn', rock: 'rock', gravel: 'gravel', snow: 'snow', tuft: 'lawn_tuft', tuftDensity: 0.3, shore: 'sand',
    patchLo: [0.86, 0.92, 0.8], patchHi: [1.06, 1.04, 0.9],
    relief: 0.55, maxRelief: 90, snowLine: 1e5, treeDensity: 0.2,
  },
  // Pine Forest: a floor of fallen needles and moss, ferns, and pines packed
  // close to the road.
  forest: {
    base: 'needles', rock: 'rock', gravel: 'gravel', snow: 'snow', tuft: 'fern_tuft', tuftDensity: 0.8, shore: 'sand',
    patchLo: [0.8, 0.8, 0.74], patchHi: [1.08, 1.04, 0.94],
    relief: 0.85, maxRelief: 140, snowLine: 1e5, treeDensity: 2.6, treeClear: 6.5,
  },
  // Desert Canyon: red sand and grit, sandstone in every cutting and cliff,
  // tufts of dry grass and no trees.
  canyon: {
    base: 'desert', rock: 'sandstone', gravel: 'gravel', snow: 'snow', tuft: 'desert_tuft', tuftDensity: 0.25, shore: 'sand',
    patchLo: [0.9, 0.86, 0.82], patchHi: [1.08, 1.02, 0.94],
    // No rock patches on the flats: top-down sandstone read as dark stains.
    relief: 0.9, maxRelief: 160, snowLine: 1e5, treeDensity: 0, outcrops: 0,
  },
};

// Paving for pavements and other flat hard surfaces built as geometry: 600 mm
// flags (2.4 m per texture tile) projected in world space on whichever axis
// the surface faces, so no UVs are needed. Kerbs and steps work too.
export function createPavingMaterial(renderer, { tint = '#ffffff' } = {}) {
  const mat = new THREE.MeshStandardMaterial({ color: tint, roughness: 0.85, metalness: 0 });
  const uniforms = { tPaveA: { value: groundTexture('paving', 'albedo', renderer) }, tPaveN: { value: groundTexture('paving', 'normal', renderer) } };
  mat.onBeforeCompile = (s) => {
    Object.assign(s.uniforms, uniforms);
    s.vertexShader = s.vertexShader
      .replace('#include <common>', '#include <common>\nvarying vec3 vPvW;\nvarying vec3 vPvN;')
      .replace('#include <worldpos_vertex>', '#include <worldpos_vertex>\nvPvW = (modelMatrix * vec4(transformed, 1.0)).xyz;\nvPvN = normalize(mat3(modelMatrix) * objectNormal);');
    s.fragmentShader = s.fragmentShader
      .replace('#include <common>', '#include <common>\nuniform sampler2D tPaveA, tPaveN;\nvarying vec3 vPvW;\nvarying vec3 vPvN;')
      .replace(
        '#include <map_fragment>',
        `vec3 pa = abs(vPvN);
        vec2 pUv = (pa.y > max(pa.x, pa.z) ? vPvW.xz : pa.x > pa.z ? vPvW.zy : vPvW.xy) / 2.4;
        vec4 pT = texture2D(tPaveA, pUv);
        diffuseColor.rgb *= pT.rgb;`,
      )
      .replace(
        '#include <normal_fragment_maps>',
        `{
          vec3 tn = texture2D(tPaveN, pUv).xyz * 2.0 - 1.0;
          vec3 q0 = dFdx(-vViewPosition), q1 = dFdy(-vViewPosition);
          vec2 st0 = dFdx(pUv), st1 = dFdy(pUv);
          vec3 N = normal;
          vec3 q1perp = cross(q1, N), q0perp = cross(N, q0);
          vec3 T = q1perp * st0.x + q0perp * st1.x;
          vec3 B = q1perp * st0.y + q0perp * st1.y;
          float det = max(dot(T, T), dot(B, B));
          float sc = det == 0.0 ? 0.0 : inversesqrt(det);
          normal = normalize(T * (tn.x * sc) + B * (tn.y * sc) + N * tn.z);
        }`,
      );
  };
  mat.customProgramCacheKey = () => 'paving';
  return mat;
}

const SHARED = /* glsl */ `
  uniform sampler2D tBaseA, tBaseN, tRockA, tRockN, tGravA, tGravN, tSnowA, tSnowN;
  uniform vec3 uPatchLo, uPatchHi;
  uniform vec4 uPatchC;
  varying vec3 vGWorld;
  varying vec3 vGNormal;
  varying vec4 vSplat;

  vec4 triA(sampler2D t, vec3 p, vec3 w, float s) {
    return texture2D(t, p.zy * s) * w.x + texture2D(t, p.xz * s) * w.y + texture2D(t, p.xy * s) * w.z;
  }
  // Triplanar normal with whiteout blending, returned in world space.
  vec3 triN(sampler2D t, vec3 p, vec3 w, vec3 n, float s) {
    vec3 tx = texture2D(t, p.zy * s).xyz * 2.0 - 1.0;
    vec3 ty = texture2D(t, p.xz * s).xyz * 2.0 - 1.0;
    vec3 tz = texture2D(t, p.xy * s).xyz * 2.0 - 1.0;
    tx = vec3(tx.xy + n.zy, abs(tx.z) * n.x);
    ty = vec3(ty.xy + n.xz, abs(ty.z) * n.y);
    tz = vec3(tz.xy + n.xy, abs(tz.z) * n.z);
    return normalize(tx.zyx * w.x + ty.xzy * w.y + tz.xyz * w.z);
  }
  // Top-down projected detail normal applied to a world normal.
  vec3 topN(sampler2D t, vec2 uv, vec3 n) {
    vec3 tn = texture2D(t, uv).xyz * 2.0 - 1.0;
    return normalize(vec3(tn.x + n.x, abs(tn.z) * n.y, tn.y + n.z));
  }
`;

export function createGroundMaterial(renderer, { far = false, simple = false, set = GROUND_SETS.alpine, patch } = {}) {
  const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.92, metalness: 0 });
  const T = (n, k) => groundTexture(n, k, renderer);
  const uniforms = {
    tBaseA: { value: T(set.base, 'albedo') },
    tBaseN: { value: T(set.base, 'normal') },
    tRockA: { value: T(set.rock, 'albedo') },
    tRockN: { value: T(set.rock, 'normal') },
    tGravA: { value: T(set.gravel, 'albedo') },
    tGravN: { value: T(set.gravel, 'normal') },
    tSnowA: { value: T(set.snow, 'albedo') },
    tSnowN: { value: T(set.snow, 'normal') },
    // Large-scale tints: lush and dry patches, and a third patch colour
    // (heather, say) with its strength in w.
    uPatchLo: { value: new THREE.Vector3(...(set.patchLo ?? [0.74, 0.84, 0.68])) },
    uPatchHi: { value: new THREE.Vector3(...(set.patchHi ?? [1.15, 1.08, 0.86])) },
    uPatchC: { value: new THREE.Vector4(...(set.patchC ?? [1, 1, 1, 0])) },
  };
  // Shore cover (sand round the sea and lakes), from the terrain's shore
  // attribute: x sand, y wet sand at the water's edge.
  const shore = !!set.shore;
  if (shore) {
    uniforms.tShoreA = { value: T(set.shore, 'albedo') };
    uniforms.tShoreN = { value: T(set.shore, 'normal') };
  }
  const detail = !far && !simple;
  mat.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms);
    shader.vertexShader = shader.vertexShader
      .replace(
        '#include <common>',
        `#include <common>
        attribute vec4 splat;
        varying vec3 vGWorld;
        varying vec3 vGNormal;
        varying vec4 vSplat;
        attribute vec3 cover;
        varying vec3 vCover;`,
      )
      .replace(
        '#include <worldpos_vertex>',
        `#include <worldpos_vertex>
        vGWorld = (modelMatrix * vec4(transformed, 1.0)).xyz;
        vGNormal = normalize(mat3(modelMatrix) * objectNormal);
        vSplat = splat;
        vCover = cover;`,
      );
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', `#include <common>\n${SHARED}\nvarying vec3 vCover;\n${shore ? 'uniform sampler2D tShoreA, tShoreN;' : ''}`)
      .replace(
        '#include <map_fragment>',
        `
        vec3 gp = vGWorld;
        vec3 gn = normalize(vGNormal);
        vec3 tw = pow(abs(gn), vec3(4.0));
        tw /= tw.x + tw.y + tw.z;
        // Rock favours the side projections so its bedding stays level on
        // slopes; only near-flat rock uses the top-down one.
        vec3 rw = pow(abs(gn) * vec3(1.0, 0.7, 1.0), vec3(4.0));
        rw /= rw.x + rw.y + rw.z;
        ${far ? `
        // Far tiles: one coarse sample per layer is plenty.
        vec4 aBase = texture2D(tBaseA, gp.xz * 0.02);
        vec4 aRock = texture2D(tRockA, gp.xz * 0.012);
        vec4 aGrav = texture2D(tGravA, gp.xz * 0.05);
        vec4 aSnow = texture2D(tSnowA, gp.xz * 0.02);
        ` : `
        // Two differently rotated grass samples, blended by low-frequency
        // noise, hide the tile repeat.
        float gN1 = texture2D(tSnowA, gp.xz * 0.011).a;
        vec2 gUv2 = mat2(0.8, -0.6, 0.6, 0.8) * gp.xz * 0.27 + 0.31;
        vec4 aBase = mix(texture2D(tBaseA, gp.xz * 0.33), texture2D(tBaseA, gUv2), smoothstep(0.35, 0.65, gN1));
        vec4 aRock = vec4(0.5);
        if (vSplat.x > 0.01) {
          aRock = triA(tRockA, gp, rw, 0.16);
          // A second, much larger sample breaks up the repeat on big faces.
          vec4 aRockM = triA(tRockA, gp + 17.0, rw, 0.037);
          aRock.rgb *= 0.55 + dot(aRockM.rgb, vec3(0.9));
          aRock.a = mix(aRock.a, aRockM.a, 0.35);
        }
        vec4 aGrav = vSplat.y > 0.01 ? texture2D(tGravA, gp.xz * 0.45) : vec4(0.5);
        vec4 aSnow = vSplat.z > 0.01 ? texture2D(tSnowA, gp.xz * 0.12) : vec4(0.5);
        `}
        // Large patches of lusher and drier grass.
        float gN2 = texture2D(tSnowA, gp.xz * 0.0031 + 0.5).a;
        aBase.rgb *= mix(uPatchLo, uPatchHi, smoothstep(0.2, 0.8, gN2));
        float gN3 = texture2D(tSnowA, gp.zx * 0.0057 + 0.27).a;
        aBase.rgb = mix(aBase.rgb, aBase.rgb * uPatchC.rgb, smoothstep(0.55, 0.7, gN3) * uPatchC.w);
        // Height blend: each layer's weight is lifted by its own height map.
        vec4 sw = vSplat;
        float wB = max(1.0 - sw.x - sw.y - sw.z, 0.0);
        vec4 hw = vec4(wB, sw.x, sw.y, sw.z) + vec4(aBase.a, aRock.a, aGrav.a, aSnow.a) * 0.6;
        float hmax = max(max(hw.x, hw.y), max(hw.z, hw.w)) - 0.22;
        vec4 bw = max(hw - hmax, 0.0) * vec4(wB, sw.x, sw.y, sw.z) + 1e-5;
        bw /= bw.x + bw.y + bw.z + bw.w;
        vec3 gcol = aBase.rgb * bw.x + aRock.rgb * bw.y + aGrav.rgb * bw.z + aSnow.rgb * bw.w;
        // Dry, sun-bleached grass on exposed spots.
        gcol = mix(gcol, gcol * vec3(1.25, 1.12, 0.8), sw.w * bw.x);
        float gRough = dot(bw, vec4(0.97, 0.88, 0.93, 0.55));
        ${shore ? `
        // Sand: lifted by its ripples so it creeps into the grass edge, and
        // darker and smoother where the water has wetted it.
        float sandW = 0.0;
        vec4 aShore = vec4(0.5);
        if (vCover.x > 0.01) {
          aShore = texture2D(tShoreA, gp.xz * ${far ? '0.05' : '0.2'});
          sandW = smoothstep(0.3, 0.6, vCover.x + (aShore.a - aBase.a) * 0.35) * (1.0 - bw.w);
          aShore.rgb *= mix(1.0, 0.62, vCover.y);
          gcol = mix(gcol, aShore.rgb, sandW);
          gRough = mix(gRough, mix(0.95, 0.55, vCover.y), sandW);
        }
        ` : ''}
        // Scorched ground where a fire went through: charcoal with drifts of
        // grey ash, a singed brown fringe, and sooty rock.
        if (vCover.z > 0.01) {
          float bN = texture2D(tSnowA, gp.xz * 0.043 + 0.13).a;
          float bN2 = texture2D(tSnowA, gp.zx * 0.21 + 0.7).a;
          float bEdge = vCover.z + (bN - 0.5) * 0.7;
          float burnW = smoothstep(0.3, 0.6, bEdge) * (1.0 - bw.w);
          vec3 burnt = mix(vec3(0.032, 0.029, 0.026) * (0.6 + aBase.a * 0.9), vec3(0.2, 0.195, 0.185) * (0.85 + aBase.a * 0.3), smoothstep(0.4, 0.9, bN2) * 0.65);
          burnt = mix(burnt, gcol * 0.4, bw.y);
          burnt = mix(burnt, gcol * 0.6, bw.z * 0.7);
          gcol = mix(gcol, gcol * vec3(0.55, 0.42, 0.3), smoothstep(0.0, 0.35, bEdge) * (1.0 - burnW) * (1.0 - bw.w));
          gcol = mix(gcol, burnt, burnW);
          gRough = mix(gRough, 0.97, burnW);
        }
        diffuseColor.rgb *= gcol;
        `,
      )
      .replace('#include <roughnessmap_fragment>', 'float roughnessFactor = gRough;')
      .replace(
        '#include <normal_fragment_maps>',
        detail
          ? `
        vec3 nBase = topN(tBaseN, gp.xz * 0.33, gn);
        vec3 nRock = bw.y > 0.01 ? triN(tRockN, gp, rw, gn, 0.16) : gn;
        vec3 nGrav = bw.z > 0.01 ? topN(tGravN, gp.xz * 0.45, gn) : gn;
        vec3 nSnow = bw.w > 0.01 ? topN(tSnowN, gp.xz * 0.12, gn) : gn;
        vec3 gN = normalize(nBase * bw.x + nRock * bw.y + nGrav * bw.z + nSnow * bw.w);
        ${shore ? 'if (sandW > 0.01) gN = normalize(mix(gN, topN(tShoreN, gp.xz * 0.2, gn), sandW));' : ''}
        normal = normalize((viewMatrix * vec4(gN, 0.0)).xyz);
        `
          : '',
      );
    patch?.(shader);
    if (!far) addLampLights(shader);
  };
  mat.customProgramCacheKey = () => `ground-${far}-${simple}-${shore}-${lampsOn()}`;
  return mat;
}

// Boulders and other props: world-space triplanar rock with moss and grass
// settling on the upward-facing parts. Works on instanced meshes.
export function createRockMaterial(renderer, set = GROUND_SETS.alpine) {
  const mat = new THREE.MeshStandardMaterial({ roughness: 0.9, metalness: 0 });
  const T = (n, k) => groundTexture(n, k, renderer);
  const uniforms = {
    tBaseA: { value: T(set.base, 'albedo') },
    tRockA: { value: T(set.rock, 'albedo') },
    tRockN: { value: T(set.rock, 'normal') },
  };
  mat.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms);
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nvarying vec3 vRW;\nvarying vec3 vRN;')
      .replace(
        '#include <worldpos_vertex>',
        `#include <worldpos_vertex>
        mat4 rM = modelMatrix;
        #ifdef USE_INSTANCING
          rM = modelMatrix * instanceMatrix;
        #endif
        vRW = (rM * vec4(transformed, 1.0)).xyz;
        vRN = normalize(mat3(rM) * objectNormal);`,
      );
    shader.fragmentShader = shader.fragmentShader
      .replace(
        '#include <common>',
        `#include <common>
        uniform sampler2D tBaseA, tRockA, tRockN;
        varying vec3 vRW;
        varying vec3 vRN;
        ${SHARED.replace(/uniform sampler2D[^;]*;/, '').replace(/varying[^;]*;/g, '')}`,
      )
      .replace(
        '#include <map_fragment>',
        `vec3 rn = normalize(vRN);
        vec3 rw = pow(abs(rn), vec3(4.0)); rw /= rw.x + rw.y + rw.z;
        vec4 ra = triA(tRockA, vRW, rw, 0.22);
        // Same large-scale tone as rock faces in the ground shader.
        ra.rgb *= 0.7 + dot(triA(tRockA, vRW + 17.0, rw, 0.037).rgb, vec3(1.1));
        // Moss and grass collect on top, broken up by the rock's own height.
        float moss = smoothstep(0.55, 0.85, rn.y + (ra.a - 0.5) * 0.6);
        vec3 grass = texture2D(tBaseA, vRW.xz * 0.5).rgb;
        diffuseColor.rgb *= mix(ra.rgb, grass * 0.9, moss);
        float rRough = mix(0.86, 0.97, moss);`,
      )
      .replace('#include <roughnessmap_fragment>', 'float roughnessFactor = rRough;')
      .replace(
        '#include <normal_fragment_maps>',
        `normal = normalize((viewMatrix * vec4(triN(tRockN, vRW, rw, rn, 0.22), 0.0)).xyz);`,
      );
  };
  mat.customProgramCacheKey = () => 'rock-prop';
  return mat;
}
